<?php include __DIR__.'/../layouts/header.php';?><div class="toolbar"><div><h1 class="page-title">Cursos</h1><p class="subtitle">Materias académicas con profesor responsable.</p></div><?php if($rol==='administrador'):?><a class="btn btn-primary" href="?accion=crear">+ Nuevo curso</a><?php endif;?></div><div class="card"><div class="card-body"><input class="search" data-search="#tabla" placeholder="Buscar curso..."><div class="table-wrap"><table class="table" id="tabla"><thead><tr><th>Código</th><th>Curso</th><th>Carrera</th><th>Profesor</th><th>Inscritos</th><?php if($rol==='administrador'):?><th>Acciones</th><?php endif;?></tr></thead><tbody><?php foreach($registros as $r):?><tr><td><span class="badge badge-primary"><?=e($r['codigo'])?></span></td><td><strong><?=e($r['nombre_curso'])?></strong><br><small><?=e($r['descripcion'])?></small></td><td><?=e($r['nombre_carrera']??'—')?></td><td><?=e($r['profesor']??'Sin asignar')?></td><td><?=e($r['total_inscritos'])?></td><?php if($rol==='administrador'):?><td><div class="actions"><a class="btn btn-light btn-sm" href="?accion=editar&id=<?=$r['id_curso']?>">Editar</a><form method="post" onsubmit="return confirm('¿Eliminar curso?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="accion" value="eliminar"><input type="hidden" name="id" value="<?=$r['id_curso']?>"><button class="btn btn-danger btn-sm">Eliminar</button></form></div></td><?php endif;?></tr><?php endforeach;?></tbody></table></div></div></div><?php if($rol==='administrador'&&$accion!=='listar'):?><div class="card" style="margin-top:18px"><div class="card-body"><h2 style="margin-top:0"><?= $registro?'Editar':'Nuevo'?> curso</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="accion" value="guardar"><div class="grid grid-2"><div class="form-group"><label class="form-label">Nombre del curso</label><input required name="nombre_curso" value="<?=e($registro['nombre_curso']??'')?>"></div><div class="form-group"><label class="form-label">Código</label><input required name="codigo" value="<?=e($registro['codigo']??'')?>"></div><div class="form-group"><label class="form-label">Carrera</label><select name="id_carrera"><option value="">Sin carrera</option><?php require_once __DIR__.'/../../models/CarreraModel.php';foreach((new CarreraModel($pdo))->obtenerTodas() as $c):?><option value="<?=$c['id_carrera']?>" <?=($registro['id_carrera']??'')==$c['id_carrera']?'selected':''?>><?=e($c['nombre_carrera'])?></option><?php endforeach;?></select></div><div class="form-group"><label class="form-label">Profesor</label><select name="id_profesor"><option value="">Sin asignar</option><?php require_once __DIR__.'/../../models/ProfesorModel.php';foreach((new ProfesorModel($pdo))->obtenerTodas() as $p):?><option value="<?=$p['id_profesor']?>" <?=($registro['id_profesor']??'')==$p['id_profesor']?'selected':''?>><?=e($p['nombre'].' '.$p['apellido'])?></option><?php endforeach;?></select></div><div class="form-group"><label class="form-label">Semestre</label><input type="number" min="1" max="20" name="semestre" value="<?=e($registro['semestre']??'')?>"></div><div class="form-group"><label class="form-label">Estado</label><select name="estado"><option value="activo" <?=($registro['estado']??'activo')==='activo'?'selected':''?>>Activo</option><option value="inactivo" <?=($registro['estado']??'')==='inactivo'?'selected':''?>>Inactivo</option></select></div></div><div class="form-group"><label class="form-label">Descripción</label><textarea name="descripcion"><?=e($registro['descripcion']??'')?></textarea></div><div class="actions"><button class="btn btn-primary">Guardar</button><a class="btn btn-light" href="/controllers/cursos.php">Cancelar</a></div></form></div></div><?php endif;?><?php include __DIR__.'/../layouts/footer.php';?>
